const BASE_W = { chest: 88, waist: 70, hips: 96, shoulder: 39, backLen: 41, sleeve: 58, inseam: 78 };

function scalePiece(tpl, sx, sy, offsetX) {
  const r = (v) => Math.round(v * 1000) / 1000;
  return {
    key: tpl.key,
    name: tpl.name,
    desc: tpl.desc,
    role: tpl.role,
    cutOnFold: false,
    bilateral: false,
    outline: tpl.outline.map(([x, y]) => [r(x * sx + offsetX), r(y * sy)]),
    curves: tpl.curves.map((c) => ({
      fromIdx: c.fromIdx,
      toIdx: c.toIdx,
      c1: [r(c.c1[0] * sx + offsetX), r(c.c1[1] * sy)],
      c2: [r(c.c2[0] * sx + offsetX), r(c.c2[1] * sy)],
    })),
    grain: tpl.grain.map(([x, y]) => [r(x * sx + offsetX), r(y * sy)]),
    notches: tpl.notches.map(([x, y]) => [r(x * sx + offsetX), r(y * sy)]),
    darts: [],
  };
}

function buildGradedPieces(templates, type, m) {
  const chest = (m && m.chest) || BASE_W.chest;
  const hips = (m && m.hips) || BASE_W.hips;
  const backLen = (m && m.backLen) || BASE_W.backLen;
  const inseam = (m && m.inseam) || BASE_W.inseam;
  const sleeve = (m && m.sleeve) || BASE_W.sleeve;

  const widthRef = (type === 'skirt' || type === 'trousers') ? (hips / BASE_W.hips) : (chest / BASE_W.chest);
  const lenRef = (type === 'trousers' || type === 'jumpsuit') ? (inseam / BASE_W.inseam) : (backLen / BASE_W.backLen);

  let cursorX = 4;
  return templates.map((tpl) => {
    const isSleeve = tpl.role.includes('sleeve');
    const sx = widthRef;
    const sy = isSleeve ? (sleeve / BASE_W.sleeve) : lenRef;
    const maxLocalX = Math.max(...tpl.outline.map((p) => p[0])) * sx;
    const piece = scalePiece(tpl, sx, sy, cursorX);
    cursorX += maxLocalX + 6;
    return piece;
  });
}

